private static volatile int volatileCounter = 0;
int threadsCount = 8, iterations = 10_000;
int expected = threadsCount * iterations;
Thread[] threads = new Thread[threadsCount];
for (int t=0;t<threadsCount;t++) {
    threads[t] = new Thread(() -> { for (int i=0;i<iterations;i++) volatileCounter++; });
}
for (Thread th : threads) th.start();
for (Thread th : threads) th.join(10_000);
System.out.println(expected + " vs " + volatileCounter); // czesto rozne!

private static volatile boolean running = true;
Thread worker = new Thread(() -> {
    long loops = 0;
    while (running && loops < 200_000_000L) loops++;
    System.out.println("zakonczono po " + loops + " iteracjach");
});
worker.start();
Thread.sleep(150);
running = false; // widoczne dla workera 'od razu' dzieki volatile
worker.join(5_000);

