class SimpleWorker implements Runnable {
    volatile boolean shutdownRequested = false;
    int cykle = 0;
    public void run() { while (!shutdownRequested) { cykle++; try { Thread.sleep(10); } catch (Exception e) {} } }
    void requestShutdown() { shutdownRequested = true; }
}
SimpleWorker sw = new SimpleWorker();
Thread t = new Thread(sw);
t.start();
Thread.sleep(300);
sw.requestShutdown();
t.join(5_000);
System.out.println(!t.isAlive() + " cykle="+sw.cykle);

