class CancelableTask implements Runnable {
    volatile boolean cancelled = false;
    int znalezione = 0;
    void cancel() { cancelled = true; }
    public void run() {
        int n = 2;
        while (!cancelled && n < 10_000_000) { if (isPrime(n)) znalezione++; n++; }
    }
    boolean isPrime(int n) { for (int i=2;i*i<=n;i++) if (n%i==0) return false; return n>1; }
}
CancelableTask task = new CancelableTask();
Thread t = new Thread(task);
t.start();
Thread.sleep(200);
task.cancel();
t.join(5_000);
System.out.println(task.znalezione);

volatile long lastHeartbeat = System.currentTimeMillis();
volatile boolean workerDone = false;
Thread w = new Thread(() -> { for (int i=0;i<5;i++) { lastHeartbeat = System.currentTimeMillis(); try { Thread.sleep(50); } catch (Exception e) {} } workerDone = true; });
Thread monitor = new Thread(() -> { int s=0; while (!workerDone && s<1000) { System.out.println(System.currentTimeMillis()-lastHeartbeat < 200 ? "OK" : "STALE"); try { Thread.sleep(20); } catch (Exception e) {} s++; } });
w.start(); monitor.start();
w.join(5_000); monitor.join(5_000);

class Statistics {
    volatile boolean collecting = true;
    private int count = 0;
    synchronized void increment() { count++; }
    synchronized int getCount() { return count; }
}
Statistics stats = new Statistics();
Thread[] t = new Thread[6];
for (int i=0;i<6;i++) t[i] = new Thread(() -> { while (stats.collecting) stats.increment(); });
for (Thread th : t) th.start();
Thread.sleep(300); stats.collecting = false;
for (Thread th : t) th.join(5_000);
System.out.println(stats.getCount()); // zawsze poprawny

boolean runExperiment(int threadsCount, int iterations) throws InterruptedException {
    counter = 0;
    Thread[] t = new Thread[threadsCount];
    for (int i=0;i<threadsCount;i++) t[i] = new Thread(() -> { for (int j=0;j<iterations;j++) counter++; });
    for (Thread th : t) th.start();
    for (Thread th : t) th.join(10_000);
    return counter != threadsCount*iterations;
}
int raceCount = 0;
for (int n=2;n<=20;n+=2) { if (runExperiment(n, 10_000)) raceCount++; }
System.out.println(raceCount + "/10 z race condition");

